const express = require('express');
const crypto = require('crypto');
const zlib = require('zlib');

const app = express();
const DEVICE_SECRET = process.env.DEVICE_SECRET || crypto.randomBytes(32).toString('hex');
const TRUSTED_SERVICES = ['config-manager', 'ota-updater', 'telemetry-hub'];

// Limit for decompressed payloads to prevent decompression bombs
const MAX_DECOMPRESSED_BYTES = 1 * 1024 * 1024; // 1 MB

// Keys that must never be assigned to prevent prototype pollution
const FORBIDDEN_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

// Firmware state store
const deviceState = {
  firmwareVersion: '2.4.1',
  lastConfigUpdate: null,
  peripherals: {},
  scheduledTasks: []
};

// HMAC-based message authentication for inter-service communication
function verifyServiceToken(token, payload, serviceId) {
  if (!TRUSTED_SERVICES.includes(serviceId)) return false;
  if (typeof token !== 'string' || !/^[0-9a-fA-F]+$/.test(token) || token.length % 2 !== 0) {
    return false;
  }
  const expected = crypto.createHmac('sha256', DEVICE_SECRET)
    .update(serviceId + ':' + payload)
    .digest('hex');
  const tokenBuf = Buffer.from(token, 'hex');
  const expectedBuf = Buffer.from(expected, 'hex');
  // timingSafeEqual throws on length mismatch; guard explicitly
  if (tokenBuf.length !== expectedBuf.length) return false;
  return crypto.timingSafeEqual(tokenBuf, expectedBuf);
}

// Decode transport envelope - handles compressed payloads from services
function decodeTransportEnvelope(envelope) {
  const header = Buffer.from(envelope.header, 'base64');
  const compressionType = header.readUInt8(0);
  const payloadVersion = header.readUInt8(1);
  const rawPayload = Buffer.from(envelope.body, 'base64');

  let decoded;
  if (compressionType === 0x01) {
    // Bound decompressed size to mitigate decompression-bomb DoS
    decoded = zlib.inflateSync(rawPayload, { maxOutputLength: MAX_DECOMPRESSED_BYTES });
  } else {
    decoded = rawPayload;
  }

  return { version: payloadVersion, data: decoded.toString('utf-8') };
}

// Configuration object hydration from validated service messages
function hydrateConfigObject(configDescriptor) {
  const type = configDescriptor.type;
  const value = configDescriptor.value;

  // Only allow primitive types and arrays for config values
  if (type === 'string') return String(value);
  if (type === 'number') return Number(value);
  if (type === 'boolean') return Boolean(value);
  if (type === 'array') return Array.isArray(value) ? value.map(v => hydrateConfigObject(v)) : [];
  if (type === 'schedule') {
    // Schedule objects use a safe JSON-based format from the config-manager
    return deserializeSchedule(value);
  }
  return null;
}

// Schedule deserialization - config-manager sends JSON schedule objects
// validated against a strict schema for cron-like structures
function deserializeSchedule(serializedData) {
  const parsed = JSON.parse(Buffer.from(serializedData, 'base64').toString('utf-8'));
  // Validate schedule schema strictly
  const allowed = ['cron', 'action', 'enabled', 'timeout'];
  const result = {};
  for (const key of allowed) {
    if (key in parsed) {
      if (key === 'cron' && typeof parsed[key] !== 'string') continue;
      if (key === 'action' && typeof parsed[key] !== 'string') continue;
      if (key === 'enabled' && typeof parsed[key] !== 'boolean') continue;
      if (key === 'timeout' && typeof parsed[key] !== 'number') continue;
      result[key] = parsed[key];
    }
  }
  return result;
}

// Apply configuration update to device state
function applyConfigUpdate(config) {
  if (config.peripherals && typeof config.peripherals === 'object') {
    for (const [key, val] of Object.entries(config.peripherals)) {
      if (FORBIDDEN_KEYS.has(key)) continue;
      deviceState.peripherals[key] = val;
    }
  }
  if (config.scheduledTasks) {
    deviceState.scheduledTasks = config.scheduledTasks;
  }
  if (config.firmwareVersion) {
    deviceState.firmwareVersion = config.firmwareVersion;
  }
  deviceState.lastConfigUpdate = new Date().toISOString();
}

// Inter-service config push endpoint
app.post('/api/v1/device/config', express.json({ limit: '1mb' }), (req, res) => {
  try {
    const { serviceId, token, envelope } = req.body;

    if (!serviceId || !token || !envelope) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    // Decode the transport envelope first to get raw payload for verification
    const decoded = decodeTransportEnvelope(envelope);

    // Verify HMAC token against the decoded payload
    if (!verifyServiceToken(token, decoded.data, serviceId)) {
      return res.status(403).json({ error: 'Authentication failed' });
    }

    // Parse the authenticated configuration payload
    const configPayload = JSON.parse(decoded.data);

    // Hydrate configuration objects
    const hydratedConfig = {};
    for (const [key, descriptor] of Object.entries(configPayload)) {
      if (FORBIDDEN_KEYS.has(key)) continue;
      hydratedConfig[key] = hydrateConfigObject(descriptor);
    }

    // Apply to device state
    applyConfigUpdate(hydratedConfig);

    res.json({ status: 'ok', applied: Object.keys(hydratedConfig) });
  } catch (err) {
    res.status(500).json({ error: 'Internal processing error' });
  }
});

// Health check endpoint
app.get('/api/v1/device/status', (req, res) => {
  res.json({
    firmware: deviceState.firmwareVersion,
    lastConfig: deviceState.lastConfigUpdate,
    uptime: process.uptime()
  });
});

app.listen(8443, '127.0.0.1', () => {
  console.log('IoT device service listening on 127.0.0.1:8443');
});
